const asText = (value, fallback = "Unknown") => {
	if (value === null || value === undefined) {
		return fallback;
	}

	const text = String(value).trim();
	return text.length ? text : fallback;
};

const hasValue = (value) => value !== undefined && value !== null && String(value).trim() !== "";

const getMergeKey = (item) => {
	return (
		item?.user_token ||
		item?.token ||
		item?.id ||
		item?.bio_id ||
		item?.edu_table_id ||
		item?.demography_table_id ||
		item?.bank_details_id ||
		item?.apply_loan_id ||
		item?.loan_id ||
		JSON.stringify(item)
	);
};

const getNestedField = (row, key) => {
	if (hasValue(row?.[key])) {
		return row[key];
	}

	const candidates = [
		row?.loanrequest,
		row?.loanData,
		row?.loan,
		row?.bankdetails,
		row?.bankData,
		row?.bank,
		row?.demography,
		row?.demographyData,
		row?.education,
		row?.educationData,
		row?.applicantBio,
		row?.bio,
		row?.data,
	];

	for (const container of candidates) {
		if (Array.isArray(container)) {
			for (const item of container) {
				if (hasValue(item?.[key])) {
					return item[key];
				}
			}
		}

		if (container && typeof container === "object" && hasValue(container?.[key])) {
			return container[key];
		}
	}

	return undefined;
};


const pickFirst = (source, keys, fallback = "Unknown") => {
	for (const key of keys) {
		const value = source?.[key];
		if (value !== undefined && value !== null && String(value).trim() !== "") {
			return asText(value, fallback);
		}
	}

	return fallback;
};

const normalizeRows = (response) => {
	if (Array.isArray(response)) {
		const uniqueRows = new Map();
		response.forEach((item) => {
			uniqueRows.set(getMergeKey(item), item);
		});
		return Array.from(uniqueRows.values());
	}

	const dataRoot = response?.data && typeof response.data === "object" ? response.data : null;
	const objectRoot = response && typeof response === "object" ? response : null;
	const roots = [objectRoot, dataRoot].filter(Boolean);

	for (const root of roots) {
		if (Array.isArray(root)) {
			const uniqueRows = new Map();
			root.forEach((item) => {
				uniqueRows.set(getMergeKey(item), item);
			});
			return Array.from(uniqueRows.values());
		}

		const arrayEntries = Object.entries(root).filter(([, value]) => Array.isArray(value));
		if (!arrayEntries.length) {
			continue;
		}

		const merged = new Map();
		arrayEntries.forEach(([, list]) => {
			list.forEach((item) => {
				const key = getMergeKey(item);
				const previous = merged.get(key) || {};
				merged.set(key, { ...previous, ...item });
			});
		});

		return Array.from(merged.values());
	}

	return [];
};

const countBy = (rows, getter) => {
	return rows.reduce((accumulator, row) => {
		const label = getter(row);
		accumulator[label] = (accumulator[label] || 0) + 1;
		return accumulator;
	}, {});
};

const getClientName = (row) => {
	const direct = asText(row?.clientName, "");
	if (direct) {
		return direct;
	}

	const firstName = asText(row?.fname, "").trim();
	const middleName = asText(row?.md_name, "").trim();
	const lastName = asText(row?.lname, "").trim();
	const fullName = `${firstName} ${middleName} ${lastName}`.replace(/\s+/g, " ").trim();

	return fullName || "";
};

