function niceLabel(key) {
  if (!key) return "";
  return key
    .replace(/_/g, " ")
    .replace(/\b\w/g, (l) => l.toUpperCase())
    .replace(/\bPsn\b/gi, "PSN")
    .replace(/\bNin\b/gi, "NIN")
    .replace(/\bBvn\b/gi, "BVN")
    .replace(/\bFname\b/gi, "First Name")
    .replace(/\bLname\b/gi, "Last Name")
    .replace(/\bd o b\b/gi, "Date Of Birth")
}


