function KeyValueGrid({ allData,filterData,type }) {
  
  if (!allData) return null;
   let  selected

   if(allData){
       selected = _.pick(allData,filterData );
       
   }
   
  const entries = Object.entries(selected)
  return (
    <Grid container spacing={2} className="mt-2">
      {entries.map(([k, v]) => (

        <Grid item xs={12} sm={6} md={4} key={k}>

          <div className="p-3 bg-white/60 rounded-lg shadow-sm border border-gray-100">
            <div className="text-xs text-gray-500">{niceLabel(k)}</div>
            <div className="mt-1 font-medium break-words">{v === null || v === undefined || v === "" ? <span className="text-gray-400">—</span> : String(v)}</div>
          </div>
           
        </Grid> 
      ))}
    </Grid>
  );


}



